#!/usr/bin/env python3
import os,sys,json,re,sqlite3,secrets,hashlib,base64,struct,threading,time,datetime,urllib.parse, mimetypes
from http.server import ThreadingHTTPServer,BaseHTTPRequestHandler
DB='/app/huddle.db'
PORT=int(os.environ.get('PORT','8000')); NODE=PORT-8000
lock=threading.RLock()
def now(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def db():
 c=sqlite3.connect(DB,timeout=20,check_same_thread=False); c.row_factory=sqlite3.Row
 c.executescript('''PRAGMA journal_mode=WAL;
 CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
 CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
